SELECT percentile_cont(0.75) within GROUP (ORDER BY value) AS median_peak_serum_glucose FROM labevents JOIN diagnoses_icd ON labevents.subject_id = diagnoses_icd.subject_id WHERE labevents.itemid = 257591002 AND labevents.charttime <= labevents.stoptime AND diagnoses_icd.icd_code = '250.0' AND labevents.subject_id IN (SELECT subject_id FROM admissions WHERE gender = 'F' AND age(CURRENT_DATE, date_trunc('year', birthdate)) = 58);